def chart(fig,title):
    fig.update_layout(title=title,paper_bgcolor='white',plot_bgcolor='white',font_color='#243447',margin=dict(l=55,r=25,t=55,b=50))
    fig.update_xaxes(showgrid=True,gridcolor='#E7EDF3'); fig.update_yaxes(showgrid=True,gridcolor='#E7EDF3')
    return fig

def number(s):
    s=str(s).strip().lower().replace(' ','').replace(',','.')
    m=re.fullmatch(r'([+-]?[0-9]*\.?[0-9]+)[×x*]10\^([+-]?[0-9]+)',s)
    if m:return float(m.group(1))*10**int(m.group(2))
    return float(s)

def fmt(x):
    if abs(x)>=1e4 or (abs(x)<1e-3 and x!=0):
        a,e=f'{x:.3e}'.split('e');return f'{a.replace(".",",")} × 10^{int(e)}'
    return f'{x:.3f}'.rstrip('0').rstrip('.').replace('.',',')

def sim(kind):
    if kind=='equilibrium':
        st.subheader('Eksperimen: Kesetimbangan Termal'); a,b=st.columns(2); ta=a.slider('T A (°C)',0,100,80); tb=b.slider('T B (°C)',0,80,20); r=st.slider('Kapasitas termal A/B',.25,4.,1.,.25); tf=(r*ta+tb)/(r+1); st.metric('T akhir model',f'{tf:.1f} °C'); t=np.linspace(0,1,100); fig=go.Figure(); fig.add_scatter(x=t,y=tf+(ta-tf)*np.exp(-5*t),name='A'); fig.add_scatter(x=t,y=tf+(tb-tf)*np.exp(-5*t),name='B'); fig.add_hline(y=tf,line_dash='dash'); st.plotly_chart(chart(fig,'Pendekatan kesetimbangan termal'),use_container_width=True)
    elif kind=='pv':
        st.subheader('Eksperimen: P–V Process Explorer'); a,b,c,d=st.columns(4); typ=a.selectbox('Proses',['Isobarik','Isokhorik','Isotermal','Adiabatik']); p=b.number_input('P awal (kPa)',20.,500.,100.,10.); v0=c.number_input('V awal (L)',.5,20.,2.,.5); v1=d.number_input('V akhir (L)',.5,20.,5.,.5); V=np.linspace(v0,v1,160)
        if typ=='Isobarik': P=np.full_like(V,p)
        elif typ=='Isokhorik': V=np.full(160,v0); P=np.linspace(p,2*p,160)
        elif typ=='Isotermal': P=p*v0/V
        else:P=p*(v0/V)**1.4
        w=np.trapezoid(P,V) if hasattr(np,'trapezoid') else np.trapz(P,V); fig=go.Figure(); fig.add_scatter(x=V,y=P,mode='lines',fill='tozeroy',name=typ); fig.update_xaxes(title='V (L)'); fig.update_yaxes(title='P (kPa)'); st.plotly_chart(chart(fig,f'Diagram P–V · {typ}'),use_container_width=True); st.metric('Usaha aproksimasi',f'{w:.2f} J')
    elif kind=='first':
        st.subheader('Eksperimen: Energy Bookkeeping'); q=st.number_input('Q (J), masuk +',-5000.,5000.,1000.,100.); w=st.number_input('W (J), oleh sistem +',-5000.,5000.,400.,100.); du=q-w; st.markdown(f'<div class="formula"><b>ΔU=Q−W={du:.2f} J</b></div>',unsafe_allow_html=True); st.plotly_chart(chart(go.Figure(go.Bar(x=['Q','W','ΔU'],y=[q,w,du])),'Neraca energi'),use_container_width=True)
    elif kind=='gas':
        st.subheader('Eksperimen: Gas Ideal'); a,b,c=st.columns(3); n=a.slider('n (mol)',.1,5.,1.,.1); T=b.slider('T (K)',200.,800.,300.,10.); Vl=c.slider('V (L)',1.,20.,5.,.5); Pk=n*8.314*T/(Vl/1000)/1000; st.metric('P',f'{Pk:.2f} kPa'); rng=np.random.default_rng(3); pts=rng.random((90,2)); fig=go.Figure(go.Scatter(x=pts[:,0],y=pts[:,1],mode='markers')); fig.update_xaxes(showticklabels=False);fig.update_yaxes(showticklabels=False,scaleanchor='x');st.plotly_chart(chart(fig,'Model partikel gas'),use_container_width=True)
    elif kind=='entropy':
        st.subheader('Eksperimen: Entropi Dua Reservoir'); a,b,c=st.columns(3); th=a.slider('Th (K)',300,1000,600,10); tc=b.slider('Tc (K)',100,500,300,10); q=c.slider('Q (J)',10,1000,100,10); 
        if tc>=th: st.warning('Pilih Th > Tc.'); return
        dh=-q/th; dc=q/tc; dt=dh+dc; st.metric('ΔS total',f'{dt:.4f} J/K'); st.plotly_chart(chart(go.Figure(go.Bar(x=['Panas','Dingin','Total'],y=[dh,dc,dt])),'Perubahan entropi'),use_container_width=True)
    elif kind=='carnot':
        st.subheader('Eksperimen: Mesin Carnot'); a,b,c=st.columns(3); th=a.slider('Th (K)',300,1200,600,10); tc=b.slider('Tc (K)',100,700,300,10); qh=c.number_input('Qh (J)',100.,10000.,1200.,100.); 
        if tc>=th: st.error('Th harus > Tc.'); return
        eta=1-tc/th; w=eta*qh; qc=qh-w; x=np.linspace(tc+1,th,100); fig=go.Figure(go.Scatter(x=x,y=1-tc/x,mode='lines'));fig.update_xaxes(title='Th (K)');fig.update_yaxes(title='Efisiensi');st.plotly_chart(chart(fig,'Efisiensi Carnot terhadap Th'),use_container_width=True); a,b,c=st.columns(3);a.metric('η',f'{eta*100:.2f}%');b.metric('W',f'{w:.2f} J');c.metric('Qc',f'{qc:.2f} J')
    elif kind=='refrigerator':
        st.subheader('Eksperimen: Refrigerator'); a,b=st.columns(2); tc=a.slider('Tc (K)',200,300,270,1); th=b.slider('Th (K)',280,350,300,1); 
        if th<=tc: st.error('Th harus > Tc.'); return
        cop=tc/(th-tc); st.metric('COP Carnot ideal',f'{cop:.2f}'); x=np.linspace(tc+1,360,120);fig=go.Figure(go.Scatter(x=x,y=tc/(x-tc),mode='lines'));fig.update_xaxes(title='Th (K)');fig.update_yaxes(title='COP');st.plotly_chart(chart(fig,'COP terhadap temperatur lingkungan'),use_container_width=True)
    elif kind=='zero':
        st.subheader('Eksperimen: Celsius ↔ Kelvin'); c=st.slider('T (°C)',-273.15,100.,20.,.05);k=c+273.15;st.metric('Kelvin',f'{k:.2f} K');x=np.linspace(-273.15,100,200);fig=go.Figure(go.Scatter(x=x,y=x+273.15,mode='lines'));fig.add_vline(x=-273.15,line_dash='dash');fig.update_xaxes(title='°C');fig.update_yaxes(title='K');st.plotly_chart(chart(fig,'Konversi temperatur'),use_container_width=True)


def home():
    st.markdown('<div class="hero"><small style="color:#800000;font-weight:800;letter-spacing:.08em">INTERACTIVE THERMODYNAMICS LABORATORY</small><h1>Belajar Termodinamika seperti berada di laboratorium.</h1><p>InTherLab menggabungkan konsep, grafik, simulasi, eksperimen virtual, kalkulator, dan kuis. Siswa tidak hanya menghitung, tetapi melihat bagaimana sistem berubah.</p></div>',unsafe_allow_html=True)
    a,b,c,d=st.columns(4)
    for col,val,label in zip([a,b,c,d],['8','40','6+','P–V'],['modul','soal kuis','eksperimen','grafik interaktif']): col.metric(label,val)
    st.subheader('Modul pembelajaran')
    for i in range(0,len(MODULES),2):
        cols=st.columns(2)
        for col,item in zip(cols,MODULES[i:i+2]):
            mid,title,desc,color,obj,subs,kind=item
            with col:
                st.markdown(f'<div class="module" style="border-top:5px solid {color}"><span class="tag">MODUL {len([x for x in MODULES if x[0]<=mid])}</span><h3>{title}</h3><p class="muted">{desc}</p><small>{len(obj)} tujuan pembelajaran · {len(subs)} submateri</small></div>',unsafe_allow_html=True)
                if st.button(f'Pelajari: {title}',key='go_'+mid,use_container_width=True): st.session_state.module=mid;st.session_state.page='Teori & Modul';st.rerun()
    st.markdown('<div class="callout"><b>Alur:</b> Pahami konsep → amati grafik → ubah variabel → interpretasikan hasil → terapkan → uji dengan kuis.</div>',unsafe_allow_html=True)


def theory():
    mid=st.selectbox('Pilih modul',[x[0] for x in MODULES],index=[x[0] for x in MODULES].index(st.session_state.module),format_func=lambda x:f'Modul {next(i+1 for i,m in enumerate(MODULES) if m[0]==x)} — {M[x][1]}')
    st.session_state.module=mid; _,title,desc,color,obj,subs,kind=M[mid]
    st.markdown(f'<small style="color:{color};font-weight:800;letter-spacing:.08em">TUJUAN PEMBELAJARAN</small><h1 style="color:{color}">{title}</h1><p class="muted">{desc}</p>',unsafe_allow_html=True)
    with st.expander('Lihat tujuan pembelajaran',expanded=True):
        for i,o in enumerate(obj,1): st.markdown(f'<div class="obj"><b>{i}.</b> {o}</div>',unsafe_allow_html=True)
    t1,t2,t3,t4=st.tabs(['Materi','Eksplorasi','Penerapan','Refleksi'])
    with t1:
        for name,text in subs:
            with st.expander(name,expanded=True): st.write(text)
    with t2: sim(kind)
    with t3:
        st.subheader('Penerapan')
        apps={'fondasi':['termometer','termos','minuman panas yang menuju setimbang'],'proses':['piston','pompa sepeda','kompresi gas'],'hukum1':['pompa sepeda','mesin','sistem tertutup'],'gas':['ban kendaraan','balon','ruang gas'],'hukum2':['arah kalor','mesin kalor','pendinginan'],'carnot':['pembangkit listrik','mesin pembakaran','batas efisiensi'],'refrigerator':['kulkas','AC','pendingin laboratorium'],'hukum3':['kriogenik','material suhu rendah','skala Kelvin']}[mid]
        for x in apps: st.markdown(f'- {x}')
        st.markdown('<div class="labbox"><b>Tantangan:</b> pilih satu fenomena, tentukan sistem–lingkungan, variabel yang berubah, arah energi, lalu pilih hukum/proses yang sesuai.</div>',unsafe_allow_html=True)
    with t4:
        for q in ['Konsep apa yang paling penting?','Grafik apa yang paling membantu?','Variabel apa yang dapat kamu ubah?','Apa prediksi kamu sebelum simulasi?','Apa bukti dari hasil simulasi?']: st.markdown('- '+q)


def lab():
    st.markdown('<small style="color:#013137;font-weight:800;letter-spacing:.08em">VIRTUAL LABORATORY</small><h1 style="color:#013137">Laboratorium Virtual</h1><p class="muted">Ubah variabel, amati grafik, dan jawab pertanyaan investigasi.</p>',unsafe_allow_html=True)
    options=[(x[0],x[1]) for x in MODULES]
    mid=st.selectbox('Pilih eksperimen',options,format_func=lambda x:x[1]);kind=M[mid][6];sim(kind)
    st.divider();st.subheader('Pertanyaan investigasi')
    for q in ['Apa variabel bebas dan variabel terikat?','Apa pola yang terlihat pada grafik?','Apa prediksi sebelum variabel diubah?','Apakah hasil sesuai teori? Jelaskan.','Apa kesimpulan berdasarkan data?']: st.markdown('- '+q)


def calculator():
    st.markdown(f'<div class="main-identity"><img src="{LOGO_TRAG}"><div class="line"></div><img class="u" src="{LOGO_UNIMED}"><div><b>InTherLab · TRAG</b><span>Interactive Thermodynamics Laboratory · Universitas Negeri Medan</span></div></div>',unsafe_allow_html=True)
    st.markdown('<small style="color:#850001;font-weight:800;letter-spacing:.08em">PHYSICS CALCULATOR</small><h1 style="color:#850001">Kalkulator Termodinamika</h1><p class="muted">Format soal: Diketahui → Ditanya → Persamaan → Substitusi → Hasil.</p>',unsafe_allow_html=True)
    typ=st.selectbox('Jenis perhitungan',['Gas Ideal','Hukum I','Usaha PΔV','Efisiensi Mesin Kalor','Efisiensi Carnot','COP Refrigerator','COP Carnot Refrigerator','Celsius ↔ Kelvin'])
    st.markdown('<div class="callout"><b>Notasi ilmiah:</b> 2e5, 2×10^5, dan 2,5×10^-3 dapat digunakan.</div>',unsafe_allow_html=True)
    try:
        if typ=='Gas Ideal':
            n=number(st.text_input('n (mol)','1'));Pp=number(st.text_input('P (Pa)','1e5'));V=number(st.text_input('V (m³)','0.02494'));T=number(st.text_input('T (K)','300'));solve=st.selectbox('Cari',['P','V','n','T']);r={'P':n*8.314*T/V,'V':n*8.314*T/Pp,'n':Pp*V/(8.314*T),'T':Pp*V/(n*8.314)}[solve];u={'P':'Pa','V':'m³','n':'mol','T':'K'}[solve];f={'P':'P=nRT/V','V':'V=nRT/P','n':'n=PV/RT','T':'T=PV/nR'}[solve]
        elif typ=='Hukum I':
            q=st.number_input('Q (J)',value=1000.);w=st.number_input('W oleh sistem (J)',value=400.);r=q-w;u='J';f='ΔU=Q−W'
        elif typ=='Usaha PΔV':
            pp=number(st.text_input('P (Pa)','1e5'));vi=number(st.text_input('V1 (m³)','2e-3'));vf=number(st.text_input('V2 (m³)','5e-3'));r=pp*(vf-vi);u='J';f='W=P(V2−V1)'
        elif typ=='Efisiensi Mesin Kalor':
            qh=number(st.text_input('Qh (J)','1e3'));qc=number(st.text_input('Qc (J)','6e2'));r=(qh-qc)/qh*100;u='%';f='η=(Qh−Qc)/Qh×100%'
        elif typ=='Efisiensi Carnot':
            th=number(st.text_input('Th (K)','600'));tc=number(st.text_input('Tc (K)','300'));r=(1-tc/th)*100;u='%';f='η=1−Tc/Th'
        elif typ=='COP Refrigerator':
            qc=number(st.text_input('Qc (J)','900'));w=number(st.text_input('W (J)','300'));r=qc/w;u='';f='COP=Qc/W'
        elif typ=='COP Carnot Refrigerator':
            tc=number(st.text_input('Tc (K)','280'));th=number(st.text_input('Th (K)','300'));r=tc/(th-tc);u='';f='COP=Tc/(Th−Tc)'
        else:
            mode=st.radio('Konversi',['°C → K','K → °C'],horizontal=True);x=st.number_input('Temperatur',value=25.0);r=x+273.15 if mode=='°C → K' else x-273.15;u='K' if mode=='°C → K' else '°C';f='K=°C+273,15' if mode=='°C → K' else '°C=K−273,15'
        st.markdown(f'<div class="formula"><b>Persamaan:</b> {f}<br><b>Hasil:</b> <span style="font-size:1.25rem"><b>{fmt(r)} {u}</b></span></div>',unsafe_allow_html=True)
    except Exception as e: st.error('Periksa format angka dan satuan.')


def data_page():
    st.markdown(f'<div class="main-identity"><img src="{LOGO_TRAG}"><div class="line"></div><img class="u" src="{LOGO_UNIMED}"><div><b>InTherLab · TRAG</b><span>Interactive Thermodynamics Laboratory · Universitas Negeri Medan</span></div></div>',unsafe_allow_html=True)
    st.markdown('<small style="color:#850001;font-weight:800">DATA & ANALISIS</small><h1 style="color:#850001">Analisis Data</h1><p class="muted">Area untuk mengolah data eksperimen virtual.</p>',unsafe_allow_html=True)
    q=np.array([200,400,600,800,1000.]);w=q*.25;du=q-w;df=pd.DataFrame({'Q (J)':q,'W (J)':w,'ΔU (J)':du});st.dataframe(df,use_container_width=True,hide_index=True);fig=go.Figure(go.Scatter(x=q,y=du,mode='lines+markers'));st.plotly_chart(chart(fig,'Q vs ΔU'),use_container_width=True);st.download_button('Unduh CSV',df.to_csv(index=False).encode(),'contoh_hukum1.csv','text/csv')
