def quiz():
    st.markdown(f'<div class="main-identity"><img src="{LOGO_TRAG}"><div class="line"></div><img class="u" src="{LOGO_UNIMED}"><div><b>InTherLab · TRAG</b><span>Interactive Thermodynamics Laboratory · Universitas Negeri Medan</span></div></div>',unsafe_allow_html=True)
    st.markdown('<small style="color:#312A44;font-weight:800">ASSESSMENT</small><h1 style="color:#312A44">Kuis Termodinamika</h1><p class="muted">5 soal per modul: konsep, grafik/interpretasi, penerapan, hitungan, dan penalaran.</p>',unsafe_allow_html=True)
    mid=st.selectbox('Modul',[x[0] for x in MODULES],format_func=lambda x:f'Modul {next(i+1 for i,m in enumerate(MODULES) if m[0]==x)} — {M[x][1]}');qs=QUIZ[mid]
    answers=[]
    with st.form('quiz_'+mid):
        for i,(q,opts,ans) in enumerate(qs,1): answers.append(st.radio(f'{i}. {q}',opts,index=None,key=f'q_{mid}_{i}'))
        submit=st.form_submit_button('Periksa jawaban',use_container_width=True)
    if submit:
        score=sum(a==opts[ans] for a,(q,opts,ans) in zip(answers,qs));st.session_state.scores[mid]=score;st.progress(score/5);st.metric('Skor',f'{score}/5')
        for i,(a,(q,opts,ans)) in enumerate(zip(answers,qs),1):
            if a==opts[ans]:st.success(f'Soal {i}: benar.')
            elif a is None:st.warning(f'Soal {i}: belum dijawab. Jawaban: {opts[ans]}.')
            else:st.error(f'Soal {i}: belum tepat. Jawaban: {opts[ans]}.')


