def home():
    st.markdown(f'<div class="main-identity"><img src="{LOGO_TRAG}"><div class="line"></div><img class="u" src="{LOGO_UNIMED}"><div><b>InTherLab · TRAG</b><span>Interactive Thermodynamics Laboratory · Universitas Negeri Medan</span></div></div>',unsafe_allow_html=True)
    p=P['home']
    st.markdown(f"""<div class="hero"><div class="hero-strip"><span style="background:{p[0]}"></span><span style="background:{p[1]}"></span><span style="background:{p[2]}"></span><span style="background:{p[3]}"></span><span style="background:{p[4]}"></span></div><small style="color:{p[0]};font-weight:900;letter-spacing:.12em">INTHERLAB · BY TRAG</small><h1 style="color:{p[0]}">Termodinamika bukan untuk dihafal.<br>Uji, lihat, dan jelaskan.</h1><p>Belajar melalui konsep, grafik, simulasi, eksperimen virtual, penerapan, dan kuis. Variabel bisa diubah; sistemnya ikut bereaksi.</p></div>""",unsafe_allow_html=True)
    st.write('')
    a,b,c,d=st.columns(4)
