def page_theme_v31(name):
    skins={'home':('#FFF3C2','#800000'),'theory':('#EAF5FB','#12284B'),'lab':('#E5F1F3','#013137'),'data':('#FFF1DC','#850001'),'quiz':('#F3EDF4','#312A44'),'about':('#EAF0F7','#102B53')}
    bg,accent=skins[name]
    st.markdown(f'<style>[data-testid="stAppViewContainer"]{{background:{bg}!important}}[data-testid="stSidebar"]{{background:{bg}!important}}h1,h2,h3,h4{{color:{accent}!important}}</style>',unsafe_allow_html=True)

def anim_buttons():
    return [dict(label='▶ Jalankan',method='animate',args=[None,dict(frame=dict(duration=80,redraw=True),transition=dict(duration=0),fromcurrent=True)]),dict(label='⏸ Pause',method='animate',args=[[None],dict(frame=dict(duration=0,redraw=False),mode='immediate')]),dict(label='↺ Ulangi',method='animate',args=[None,dict(frame=dict(duration=80,redraw=True),transition=dict(duration=0),fromcurrent=False,mode='immediate')])]

def console(title,subtitle):
    st.markdown(f'<div class="lab-console"><div style="font-size:.72rem;font-weight:950;letter-spacing:.13em;color:#267376">VIRTUAL EXPERIMENT</div><h2 class="lab-console-title" style="margin:.2rem 0">{title}</h2><div class="lab-instruction">{subtitle}</div></div>',unsafe_allow_html=True)

def rich_sim_v31(kind):
    if kind=='equilibrium':
        console('Kesetimbangan Termal','Ubah temperatur awal. Tekan ▶ Jalankan pada grafik untuk melihat kedua benda mendekati temperatur setimbang.')
        a,b,c=st.columns(3); ta=a.slider('Benda A — T awal (°C)',0,100,80,1,key='v31_ta'); tb=b.slider('Benda B — T awal (°C)',0,100,20,1,key='v31_tb'); r=c.slider('Kapasitas termal A/B',.25,4.,1.,.25,key='v31_r')
        tf=(r*ta+tb)/(r+1); t=np.linspace(0,1,45); ya=tf+(ta-tf)*np.exp(-5*t); yb=tf+(tb-tf)*np.exp(-5*t)
        fig=go.Figure([go.Scatter(x=t[:1],y=ya[:1],mode='lines+markers',name='A'),go.Scatter(x=t[:1],y=yb[:1],mode='lines+markers',name='B')]); fig.frames=[go.Frame(data=[go.Scatter(x=t[:i+1],y=ya[:i+1]),go.Scatter(x=t[:i+1],y=yb[:i+1])],name=str(i)) for i in range(1,len(t))]; fig.add_hline(y=tf,line_dash='dash',line_color='#267376'); fig.update_layout(updatemenus=[dict(type='buttons',buttons=anim_buttons(),x=.02,y=1.14)],xaxis_title='Waktu relatif',yaxis_title='Temperatur (°C)'); st.plotly_chart(chart(fig,'Temperatur menuju kesetimbangan'),use_container_width=True); st.markdown(f'<div class="sim-readout">Temperatur akhir model<br><span class="value">{tf:.1f} °C</span></div>',unsafe_allow_html=True)
    elif kind=='pv':
        console('Piston & Diagram P–V','Pilih proses dan kondisi awal. Jalankan animasi untuk melihat state gas bergerak pada lintasan P–V. Luas di bawah lintasan berkaitan dengan usaha.')
        a,b,c,d=st.columns(4); typ=a.selectbox('Proses',['Isobarik','Isokhorik','Isotermal','Adiabatik'],key='v31_pvtype'); p=b.number_input('P awal (kPa)',20.,500.,100.,10.,key='v31_p'); v0=c.number_input('V awal (L)',.5,20.,2.,.5,key='v31_v0'); v1=d.number_input('V akhir (L)',.5,20.,5.,.5,key='v31_v1')
        V=np.linspace(v0,v1,45)
        if typ=='Isobarik': P=np.full_like(V,p)
        elif typ=='Isokhorik': V=np.full_like(V,v0); P=np.linspace(p,2*p,len(V))
        elif typ=='Isotermal': P=p*v0/V
        else: P=p*(v0/V)**1.4
        w=float(np.trapezoid(P,V) if hasattr(np,'trapezoid') else np.trapz(P,V)); fig=go.Figure([go.Scatter(x=V[:1],y=P[:1],mode='lines',line=dict(color='#267376',width=4),name='Lintasan'),go.Scatter(x=[V[0]],y=[P[0]],mode='markers',marker=dict(size=14,color='#F3B900'),name='State')]); fig.frames=[go.Frame(data=[go.Scatter(x=V[:i+1],y=P[:i+1]),go.Scatter(x=[V[i]],y=[P[i]])],name=str(i)) for i in range(1,len(V))]; fig.update_layout(updatemenus=[dict(type='buttons',buttons=anim_buttons(),x=.02,y=1.14)],xaxis_title='Volume V (L)',yaxis_title='Pressure P (kPa)'); st.plotly_chart(chart(fig,f'P–V Explorer · {typ}'),use_container_width=True); x,y,z=st.columns(3); x.metric('State awal',f'{P[0]:.0f} kPa · {V[0]:.2f} L'); y.metric('State akhir',f'{P[-1]:.0f} kPa · {V[-1]:.2f} L'); z.metric('Usaha',f'{w:.1f} J')
    elif kind=='first':
        console('Neraca Energi — Hukum I','Ubah Q dan W. Lihat bagaimana energi yang masuk/keluar memengaruhi perubahan energi internal.')
        a,b=st.columns(2); q=a.slider('Q — kalor masuk sistem (J)',-3000,5000,1000,100,key='v31_q'); w=b.slider('W — usaha oleh sistem (J)',-3000,5000,400,100,key='v31_w'); du=q-w
        fig=go.Figure(go.Bar(x=['Q','W','ΔU'],y=[q,w,du],text=[f'{q} J',f'{w} J',f'{du} J'],textposition='auto')); st.plotly_chart(chart(fig,'Energy Bookkeeping'),use_container_width=True); st.markdown(f'<div class="sim-readout">Konvensi: W = usaha oleh sistem<br><span class="value">ΔU = Q − W = {du} J</span></div>',unsafe_allow_html=True)
    elif kind=='gas':
        console('Chamber Gas Ideal — Partikel & Besaran Makro','Ubah T atau V. Tekan ▶ Jalankan untuk melihat partikel bergerak dan hubungkan representasi mikroskopik dengan P = nRT/V.')
        a,b,c=st.columns(3); n=a.slider('n (mol)',.1,3.,1.,.1,key='v31_n'); T=b.slider('T (K)',200.,800.,300.,10.,key='v31_T'); Vl=c.slider('V (L)',1.,20.,5.,.5,key='v31_V'); Pk=n*8.314*T/(Vl/1000)/1000
        rng=np.random.default_rng(7); base=rng.random((45,2)); frames=[]
        for i in range(25):
            pts=(base+rng.normal(0,.018,size=base.shape)*(T/300)*(i+1))%1; frames.append(go.Frame(data=[go.Scatter(x=pts[:,0],y=pts[:,1],mode='markers')],name=str(i)))
        fig=go.Figure(frames[0].data); fig.frames=frames; fig.update_traces(marker=dict(size=9,color='#267376')); fig.update_layout(xaxis=dict(range=[0,1],showticklabels=False,title='Ruang gas (model 2D)'),yaxis=dict(range=[0,1],showticklabels=False,scaleanchor='x'),updatemenus=[dict(type='buttons',buttons=anim_buttons(),x=.02,y=1.14)]); st.plotly_chart(chart(fig,'Gerak partikel gas ideal'),use_container_width=True); a,b=st.columns(2); a.metric('Tekanan model',f'{Pk:.2f} kPa'); b.metric('T / V',f'{T:.0f} K / {Vl:.1f} L')
    elif kind=='entropy':
        console('Entropi — Dua Reservoir','Bandingkan perubahan entropi reservoir panas dan dingin. Ubah Q, Th, dan Tc.')
        a,b,c=st.columns(3); th=a.slider('Th (K)',300,1000,600,10,key='v31_th'); tc=b.slider('Tc (K)',100,500,300,10,key='v31_tc'); q=c.slider('Q (J)',10,1000,100,10,key='v31_eq')
        if tc>=th: st.error('Harus Th > Tc.'); return
        ds_h=-q/th; ds_c=q/tc; total=ds_h+ds_c; fig=go.Figure(go.Bar(x=['ΔS panas','ΔS dingin','ΔS total'],y=[ds_h,ds_c,total],text=[f'{ds_h:.3f}',f'{ds_c:.3f}',f'{total:.3f}'],textposition='auto')); st.plotly_chart(chart(fig,'Perubahan entropi'),use_container_width=True); st.markdown(f'<div class="sim-readout">ΔS total<br><span class="value">{total:.4f} J/K</span></div>',unsafe_allow_html=True)
    elif kind=='carnot':
        console('Mesin Carnot — Siklus Ideal','Ubah temperatur reservoir. Lihat batas efisiensi Carnot dan neraca Qh = W + Qc.')
        a,b,c=st.columns(3); th=a.slider('Th (K)',300,1200,600,10,key='v31_cth'); tc=b.slider('Tc (K)',100,700,300,10,key='v31_ctc'); qh=c.number_input('Qh (J)',100.,10000.,1200.,100.,key='v31_cqh')
        if tc>=th: st.error('Harus Th > Tc.'); return
        eta=1-tc/th; W=eta*qh; Qc=qh-W; x=np.linspace(tc+1,th,120); fig=go.Figure(go.Scatter(x=x,y=1-tc/x,mode='lines',line=dict(color='#F8650C',width=4))); fig.add_trace(go.Scatter(x=[th],y=[eta],mode='markers',marker=dict(size=14,color='#850001'))); fig.update_layout(xaxis_title='Th (K)',yaxis_title='Efisiensi η',updatemenus=[dict(type='buttons',buttons=anim_buttons(),x=.02,y=1.14)]); st.plotly_chart(chart(fig,'Efisiensi Carnot'),use_container_width=True); a,b,c=st.columns(3); a.metric('η',f'{eta*100:.2f}%'); b.metric('W',f'{W:.1f} J'); c.metric('Qc',f'{Qc:.1f} J')
    elif kind=='refrigerator':
        console('Refrigerator — Aliran Kalor','Jalankan animasi untuk memvisualisasikan aliran konseptual kalor dari ruang dingin menuju lingkungan dengan bantuan kerja eksternal.')
        a,b=st.columns(2); tc=a.slider('Tc (K)',200,300,270,1,key='v31_rtc'); th=b.slider('Th (K)',280,350,300,1,key='v31_rth')
        if th<=tc: st.error('Harus Th > Tc.'); return
        cop=tc/(th-tc); xx=np.linspace(0,10,35); fig=go.Figure(go.Scatter(x=xx[:1],y=np.sin(xx[:1]),mode='lines+markers',line=dict(color='#267376',width=5))); fig.frames=[go.Frame(data=[go.Scatter(x=xx[:i+1],y=np.sin(xx[:i+1]),mode='lines+markers')],name=str(i)) for i in range(1,len(xx))]; fig.update_layout(updatemenus=[dict(type='buttons',buttons=anim_buttons(),x=.02,y=1.14)],xaxis_title='Proses relatif',yaxis_title='Aliran kalor (representasi)'); st.plotly_chart(chart(fig,'Visualisasi aliran kalor'),use_container_width=True); st.markdown(f'<div class="sim-readout">COP Carnot ideal<br><span class="value">{cop:.2f}</span></div>',unsafe_allow_html=True)
    elif kind=='zero':
        console('Temperatur — Celsius ↔ Kelvin','Gerakkan temperatur. Perhatikan bahwa Kelvin menggunakan nol absolut sebagai titik acuan.')
        c=st.slider('T (°C)',-273.15,100.,20.,.05,key='v31_zero'); k=c+273.15; x=np.linspace(-273.15,100,200); fig=go.Figure(go.Scatter(x=x,y=x+273.15,mode='lines',line=dict(color='#0055A0',width=4))); fig.add_trace(go.Scatter(x=[c],y=[k],mode='markers',marker=dict(size=14,color='#F00000'))); fig.update_layout(xaxis_title='°C',yaxis_title='K'); st.plotly_chart(chart(fig,'Hubungan Celsius–Kelvin'),use_container_width=True); st.metric('T absolut',f'{k:.2f} K')

def home_v31():
    page_theme_v31('home'); p=P['home']
    st.markdown(f'<div class="main-identity"><img src="{LOGO_TRAG}"><div class="line"></div><img class="u" src="{LOGO_UNIMED}"><div><b>InTherLab · TRAG</b><span>Interactive Thermodynamics Laboratory · Universitas Negeri Medan</span></div></div>',unsafe_allow_html=True)
    st.markdown(f'<div style="background:{p[0]};border-radius:26px;padding:38px 42px;color:#fff"><div style="font-size:.75rem;font-weight:950;letter-spacing:.14em;color:#FFE100">INTHERLAB · BY TRAG</div><h1 style="font-size:clamp(2.5rem,6vw,5rem);line-height:1;color:#fff!important;margin:.35rem 0 1rem">Termodinamika<br>bukan untuk dihafal.</h1><p style="max-width:820px;color:#FFF3E8;font-size:1.08rem;line-height:1.7">Uji fenomena. Gerakkan sistem. Baca grafik. Jelaskan dengan fisika.</p></div>',unsafe_allow_html=True)
