def resolve_lab_v33(value):
    """Accept module id, title, (id,title), or simulation kind and return module id."""
    ids = [x[0] for x in MODULES]
    if isinstance(value, (tuple, list)):
        for item in value:
            if item in ids:
                return item
        if len(value) > 1:
            title = str(value[1]).strip().lower()
            for item in MODULES:
                if item[1].strip().lower() == title:
                    return item[0]
    if isinstance(value, str):
        if value in ids:
            return value
        low=value.strip().lower()
        for item in MODULES:
            if item[1].strip().lower()==low:
                return item[0]
            if item[6].strip().lower()==low:
                return item[0]
    return "fondasi"

def lab_v33():
    page_theme_v31('lab')
    st.markdown(f'<div class="main-identity"><img src="{LOGO_TRAG}"><div class="line"></div><img class="u" src="{LOGO_UNIMED}"><div><b>InTherLab · TRAG</b><span>Interactive Thermodynamics Laboratory · Universitas Negeri Medan</span></div></div>',unsafe_allow_html=True)
    st.markdown('<div style="background:#013137;border-radius:25px;padding:30px;color:#fff"><div style="font-size:.74rem;font-weight:950;letter-spacing:.14em;color:#C1D9DE">VIRTUAL LABORATORY · INVESTIGATE</div><h1 style="color:#fff!important">Predict. Experiment. Measure. Explain.</h1><p style="color:#E4F2F3;max-width:850px">Jangan mulai dari rumus. Buat prediksi, manipulasi sistem, baca grafik, lalu gunakan data sebagai bukti.</p></div>',unsafe_allow_html=True)

    raw = st.session_state.get('lab_experiment','fondasi')
    mid = resolve_lab_v33(raw)
    options=[x[0] for x in MODULES]
    mid = st.selectbox('Pilih ruang eksperimen',options,index=options.index(mid),format_func=lambda x:f'⚗  {M[x][1]}',key='v33_lab_room')
    st.session_state.lab_experiment=mid
    title=M[mid][1]
    kind=str(M[mid][6]).strip().lower()
    info=LAB_INFO_V33[mid]

    st.markdown(f'<div class="lab-mission-v33"><div class="eyebrow">MISSION · {title.upper()}</div><h3>{info["mission"]}</h3><p><b>Target:</b> manipulasi variabel dan gunakan grafik/data untuk membuktikan penjelasanmu.</p></div>',unsafe_allow_html=True)

    if 'v33_prediction' not in st.session_state or st.session_state.get('v33_prediction_mid') != mid:
        st.session_state.v33_prediction = None
        st.session_state.v33_prediction_mid = mid

    st.markdown('<div class="lab-predict-v33"><h4>🤔 PREDIKSI SEBELUM EKSPERIMEN</h4><p>Pilih jawabanmu dulu. Tidak apa-apa jika salah — simulasi adalah tempat untuk mengujinya.</p></div>',unsafe_allow_html=True)
    pred=st.radio('Prediksimu:',info['options'],index=None,key=f'v33_pred_{mid}')
    if pred is not None:
        st.session_state.v33_prediction = info['options'].index(pred)
        st.session_state.v33_prediction_mid = mid

    st.markdown('<div class="lab-status-v33"><b>LANGKAH 2 · RUN THE EXPERIMENT</b><br>Gunakan kontrol di bawah, tekan ▶ pada grafik, lalu amati perubahan state dan hubungan antarvariabel.</div>',unsafe_allow_html=True)

    # This is the critical fix: pass ONLY the simulation kind, never (id,title).
    try:
        rich_sim_v31(kind)
    except KeyError:
        # Defensive fallback for older mappings: normalize whatever was passed.
        rich_sim_v31(M[resolve_lab_v33(kind)][6])

    p=st.session_state.get('v33_prediction')
    if p is not None:
        correct=(p==info['answer'])
        st.markdown(f'<div class="lab-status-v33"><b>CHECK YOUR PREDICTION</b><br>{"✓ Prediksimu sesuai dengan model." if correct else "↺ Prediksimu berbeda dari hasil model — justru ini bagian penting dari eksperimen."}<br><small>{info["hint"]}</small></div>',unsafe_allow_html=True)

    st.markdown('<div class="lab-notebook-v33"><h3>📓 LAB NOTEBOOK</h3><p><b>Observasi yang perlu dicatat:</b></p><ul><li>Variabel apa yang kamu ubah?</li><li>Variabel apa yang paling jelas berubah?</li><li>Bagian grafik mana yang menjadi bukti?</li><li>Apakah hasil sesuai prediksi? Mengapa?</li></ul></div>',unsafe_allow_html=True)

    a,b,c=st.columns(3)
    with a:
        st.text_area('Catatan observasi',key=f'v33_note_{mid}',height=110,placeholder='Tuliskan apa yang kamu amati...')
    with b:
        st.text_area('Bukti dari grafik/data',key=f'v33_evidence_{mid}',height=110,placeholder='Contoh: P meningkat ketika V menurun...')
    with c:
        st.text_area('Kesimpulan',key=f'v33_conclusion_{mid}',height=110,placeholder='Jelaskan menggunakan konsep fisika...')

